// How do I get selected shapes in a presentation?

// Access the list of shapes from a selection and count them in a presentation.

const presentation = Api.GetPresentation();
const slide = presentation.GetSlideByIndex(0);
slide.RemoveAllObjects();

const fill1 = Api.CreateSolidFill(Api.RGB(0, 100, 200));
const stroke1 = Api.CreateStroke(0, Api.CreateNoFill());
const shape1 = Api.CreateShape('rect', 80 * 36000, 20 * 36000, fill1, stroke1);
shape1.SetPosition(0, 0);
slide.AddObject(shape1);

const fill2 = Api.CreateSolidFill(Api.RGB(0, 200, 100));
const stroke2 = Api.CreateStroke(0, Api.CreateNoFill());
const shape2 = Api.CreateShape('ellipse', 60 * 36000, 20 * 36000, fill2, stroke2);
shape2.SetPosition(100 * 36000, 0);
slide.AddObject(shape2);

shape1.Select();
const selection = Api.GetSelection();
const shapes = selection.GetShapes();
const result = 'Selected shapes count: ' + shapes.length;

const outShapeFill = Api.CreateSolidFill(Api.RGB(50, 70, 180));
const outShapeStroke = Api.CreateStroke(0, Api.CreateNoFill());
const outShape = Api.CreateShape('rect', 160 * 36000, 30 * 36000, outShapeFill, outShapeStroke);
outShape.SetPosition(0, 30 * 36000);
const outDoc = outShape.GetDocContent();
const outParagraph = outDoc.GetElement(0);
outParagraph.AddText(result);
slide.AddObject(outShape);

// How do I access selected slides in a presentation?

// Get the count of selected slides using the selection object in a presentation.

const presentation = Api.GetPresentation();
const slide = presentation.GetSlideByIndex(0);
slide.RemoveAllObjects();

const selection = Api.GetSelection();
let text = 'Initial selected slides count: ' + selection.GetSlides().length + '\n';

const outShapeFill = Api.CreateSolidFill(Api.RGB(50, 70, 180));
const outShapeStroke = Api.CreateStroke(0, Api.CreateNoFill());
const outShape = Api.CreateShape('rect', 160 * 36000, 30 * 36000, outShapeFill, outShapeStroke);
outShape.SetPosition(0, 30 * 36000);

const outDoc = outShape.GetDocContent();
const outParagraph = outDoc.GetElement(0);
outParagraph.AddText(text);
slide.AddObject(outShape);

// How do I determine what is selected in a presentation?

// Check the selection type before and after adding a shape in a presentation.

const presentation = Api.GetPresentation();
const slide = presentation.GetSlideByIndex(0);
slide.RemoveAllObjects();
const selection = Api.GetSelection();

let type = selection.GetType();
let text = 'Type: ' + type + ' (no selection scenario)\n';

const fill = Api.CreateSolidFill(Api.RGB(0, 0, 0));
const stroke = Api.CreateStroke(0, Api.CreateNoFill());
const shape = Api.CreateShape('rect', 200 * 36000, 10 * 36000, fill, stroke);
slide.AddObject(shape);
shape.Select();

type = selection.GetType();
text += 'Type: ' + type + ' (shape added scenario)\n';

const outShapeFill = Api.CreateSolidFill(Api.RGB(50, 70, 180));
const outShapeStroke = Api.CreateStroke(0, Api.CreateNoFill());
const outShape = Api.CreateShape('rect', 200 * 36000, 30 * 36000, outShapeFill, outShapeStroke);
outShape.SetPosition(0, 20 * 36000);

const outDoc = outShape.GetDocContent();
const outParagraph = outDoc.GetElement(0);
outParagraph.AddText(text);
slide.AddObject(outShape);

// How do I check whether anything is selected in a presentation?

// Test if the selection contains items before and after selecting a shape in a presentation.

const presentation = Api.GetPresentation();
const slide = presentation.GetSlideByIndex(0);
slide.RemoveAllObjects();

const selection = Api.GetSelection();
let text = 'Step 1 - Is selection empty: ' + selection.IsEmpty() + '\n';

const fill = Api.CreateSolidFill(Api.RGB(0, 100, 200));
const stroke = Api.CreateStroke(0, Api.CreateNoFill());
const shape = Api.CreateShape('rect', 100 * 36000, 100 * 36000, fill, stroke);
shape.SetPosition(0, 0);
slide.AddObject(shape);
shape.Select();
text += 'Step 2 - Is selection empty: ' + selection.IsEmpty();

const outFill = Api.CreateSolidFill(Api.RGB(50, 70, 180));
const outStroke = Api.CreateStroke(0, Api.CreateNoFill());
const outShape = Api.CreateShape('rect', 200 * 36000, 30 * 36000, outFill, outStroke);
outShape.SetPosition(0, 110 * 36000);

const outDoc = outShape.GetDocContent();
const outParagraph = outDoc.GetElement(0);
outParagraph.AddText(text);
slide.AddObject(outShape);
